private static SchemaApi.IterableTypeValue iterableValueToProto(FieldType elementType,Iterable values){
  try {
    return IterableTypeValue.newBuilder().addAllElement(Iterables.transform(values,e -> fieldValueToProto(elementType,e))).build();
  } catch (NullPointerException | IllegalArgumentException e) {
    // 处理异常或重新抛出
    throw e;
  }
}
